#!/bin/bash
# Intune Linux platform script: enforce ai-governance hooks (machine-wide) for __AGENT__.
# Generated by intune/build_intune_packages.py, version __VERSION__.
#
# Intune settings: Execution context = Root, Execution frequency = Every 1 hour,
# Execution retries = 3. Every run re-applies the hooks and policies, which
# restores anything a user removed and covers users created since the last run.
set -euo pipefail

VERSION="__VERSION__"
AGENT="__AGENT__"
API_URL="__API_URL__"
TOKEN="__TOKEN__"
KIRO_POLICY="__KIRO_POLICY_LINUX__"
IDC_START_URL="__IDC_START_URL__"
IDC_REGION="__IDC_REGION__"
SETTINGS_B64="__SETTINGS_B64__"
GOV_DIR="/opt/ai-governance"
LOG="/var/log/ai-governance-intune.log"

log() { echo "$(date -Is) $*" | tee -a "$LOG"; }

if [ "$(id -u)" -ne 0 ]; then
  echo "Must run as root (set Execution context = Root in Intune)." >&2
  exit 1
fi

PYTHON="$(command -v python3 || true)"
if [ -z "$PYTHON" ]; then
  log "python3 not found; installing"
  apt-get update -qq && apt-get install -y -qq python3 >/dev/null
  PYTHON="$(command -v python3)"
fi

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
base64 -d > "$WORK/payload.tar.gz" <<'PAYLOAD'
__PAYLOAD_B64__
PAYLOAD
tar -xzf "$WORK/payload.tar.gz" -C "$WORK"

# The token reaches the installer through the environment, not the command line.
export GOV_API_TOKEN="$TOKEN"
ARGS=(--agent "$AGENT" --scope managed --api-url "$API_URL" --token-store file --python "$PYTHON")
[ "$AGENT" != "kiro" ] && ARGS+=(--lock-hooks)
[ -n "$KIRO_POLICY" ] && ARGS+=(--kiro-policy-path "$KIRO_POLICY")
[ -n "$IDC_START_URL" ] && ARGS+=(--idc-start-url "$IDC_START_URL")
[ -n "$IDC_REGION" ] && ARGS+=(--idc-region "$IDC_REGION")
if [ -n "$SETTINGS_B64" ]; then
  # Extra hook settings (--set at build time); $WORK is removed on exit.
  printf '%s' "$SETTINGS_B64" | base64 -d > "$WORK/settings.env"
  ARGS+=(--settings-file "$WORK/settings.env")
fi

"$PYTHON" "$WORK/install_hooks.py" "${ARGS[@]}" >> "$LOG" 2>&1

unset GOV_API_TOKEN
chown -R root:root "$GOV_DIR"
chmod 755 "$GOV_DIR" "$GOV_DIR/governance_hook.py"
chmod 644 "$GOV_DIR/governance.env" "$GOV_DIR/api_token"
echo "$VERSION" > "$GOV_DIR/VERSION"
log "ai-governance $VERSION enforced for $AGENT"
